1	package fleet
2	
3	import (
4		"errors"
5		"sort"
6		"sync"
7		"time"
8	)
9	
10	var (
11		ErrDeviceNotFound  = errors.New("device not found")
12		ErrBatchConflict   = errors.New("batch conflicts with stored events")
13		ErrRuleNotFound    = errors.New("rule not found")
14		ErrAlertNotFound   = errors.New("alert not found")
15		ErrRuleConflict    = errors.New("rule already exists")
16		ErrVersionConflict = errors.New("rule version conflict")
17		ErrInvalidRule     = errors.New("invalid rule")
18	)
19	
20	// Rule is a per-device threshold rule. It judges only samples accepted while
21	// enabled; it never backfills history. Device and ID are immutable after
22	// creation. Version starts at 1 and bumps on every successful update.
23	type Rule struct {
24		ID        string    `json:"id"`
25		Metric    string    `json:"metric"`
26		Trigger   float64   `json:"trigger"`
27		Recover   float64   `json:"recover"`
28		Enabled   bool      `json:"enabled"`
29		Version   int64     `json:"version"`
30		CreatedAt time.Time `json:"createdAt"`
31		UpdatedAt time.Time `json:"updatedAt"`
32	}
33	
34	// Alert is one threshold crossing. It retains the rule version and the
35	// metric/thresholds in force when it fired. A natural recovery records the
36	// recovery sample's sequence, value and observed time; an end caused by a rule
37	// update records the server time and reason instead.
38	type Alert struct {
39		ID                int64      `json:"id"`
40		RuleID            string     `json:"ruleId"`
41		RuleVersion       int64      `json:"ruleVersion"`
42		Metric            string     `json:"metric"`
43		Trigger           float64    `json:"trigger"`
44		Recover           float64    `json:"recover"`
45		Status            string     `json:"status"` // "active" | "ended"
46		TriggerSequence   int64      `json:"triggerSequence"`
47		TriggerValue      float64    `json:"triggerValue"`
48		TriggerObservedAt time.Time  `json:"triggerObservedAt"`
49		RecoverSequence   *int64     `json:"recoverSequence,omitempty"`
50		RecoverValue      *float64   `json:"recoverValue,omitempty"`
51		RecoverObservedAt *time.Time `json:"recoverObservedAt,omitempty"`
52		EndedAt           *time.Time `json:"endedAt,omitempty"`
53		EndReason         string     `json:"endReason,omitempty"` // "recovered" | "rule_changed"
54		AcknowledgedAt    *time.Time `json:"acknowledgedAt,omitempty"`
55	}
56	
57	const (
58		alertStatusActive    = "active"
59		alertStatusEnded     = "ended"
60		endReasonRecovered   = "recovered"
61		endReasonRuleChanged = "rule_changed"
62	)
63	
64	// ruleState pairs a rule with the id of its currently active alert (0 when
65	// none).
66	type ruleState struct {
67		rule          Rule
68		activeAlertID int64
69	}
70	
71	type Device struct {
72		ID            string             `json:"id"`
73		Site          string             `json:"site"`
74		RegisteredAt  time.Time          `json:"registeredAt"`
75		LastSeenAt    time.Time          `json:"lastSeenAt"`
76		LastTelemetry map[string]float64 `json:"lastTelemetry,omitempty"`
77	}
78	
79	// Event is a single telemetry sample retained in a device's history.
80	type Event struct {
81		Sequence   int64              `json:"sequence"`
82		ObservedAt time.Time          `json:"observedAt"`
83		Values     map[string]float64 `json:"values"`
84	}
85	
86	// Sample is one replayed sample, decoded from the replay request body.
87	type Sample struct {
88		EventID    string
89		ObservedAt time.Time
90		Values     map[string]float64
91	}
92	
93	// ReplayReceipt summarises the outcome of a replay batch.
94	type ReplayReceipt struct {
95		BatchID      string         `json:"batchId"`
96		NewCount     int            `json:"newCount"`
97		Duplicate    int            `json:"duplicateCount"`
98		SampleStatus []SampleStatus `json:"samples"`
99	}
100	
101	// SampleStatus reports the history sequence assigned to (or reused by) a sample.
102	type SampleStatus struct {
103		EventID   string `json:"eventId"`
104		Sequence  int64  `json:"sequence"`
105		Duplicate bool   `json:"duplicate"`
106	}
107	
108	// HistoryFilter narrows a history query by observed-time range. Zero times mean
109	// the bound is open.
110	type HistoryFilter struct {
111		From time.Time
112		To   time.Time
113	}
114	
115	// StoredBatch records the ordered samples an accepted batchId committed along
116	// with the receipt returned on first acceptance, so a repeated batchId can be
117	// checked for identical content and replayed with the original receipt.
118	type storedBatch struct {
119		samples []Sample
120		receipt ReplayReceipt
121	}
122	
123	type deviceState struct {
124		device  Device
125		events  []Event          // history ordered by sequence (sequence = index + 1)
126		byEvent map[string]int64 // eventId -> sequence
127		batches map[string]storedBatch
128		rules   map[string]*ruleState
129		alerts  []*Alert // per-device, ordered by alert id (id = index + 1)
130		config  *configState
131		tasks   []*taskState          // per-device, ordered by task id (id = index + 1)
132		tasksByRequest map[string]*taskState // requestId -> first task
133	}
134	
135	type Store struct {
136		mu      sync.RWMutex
137		devices map[string]*deviceState
138		now     func() time.Time
139	
140		// wal is nil in memory mode. When set, every mutation is appended and
141		// synced here before in-memory state changes or success is returned.
142		wal walSink
143		iid []byte // data-directory instance id bound into history cursors
144	}
145	
146	func NewStore() *Store {
147		return &Store{devices: make(map[string]*deviceState), now: time.Now}
148	}
149	
150	// instanceID identifies the backing data directory; cursors are scoped to it.
151	// It is nil in memory mode.
152	func (s *Store) instanceID() []byte {
153		s.mu.RLock()
154		defer s.mu.RUnlock()
155		return s.iid
156	}
157	
158	// Exists reports whether a device is registered.
159	func (s *Store) Exists(id string) bool {
160		s.mu.RLock()
161		defer s.mu.RUnlock()
162		_, ok := s.devices[id]
163		return ok
164	}
165	
166	func (s *Store) Register(id, site string) (Device, bool, error) {
167		s.mu.Lock()
168		defer s.mu.Unlock()
169		if state, ok := s.devices[id]; ok {
170			return cloneDevice(state.device), false, nil
171		}
172		now := s.now().UTC()
173		device := Device{ID: id, Site: site, RegisteredAt: now, LastSeenAt: now}
174		if s.wal != nil {
175			if err := s.wal.appendRecord(recRegister, walRegister{
176				ID: id, Site: site, RegisteredAt: now, LastSeenAt: now,
177			}); err != nil {
178				return Device{}, false, storageUnavailable(err)
179			}
180		}
181		s.devices[id] = &deviceState{
182			device:  device,
183			byEvent: make(map[string]int64),
184			batches: make(map[string]storedBatch),
185			rules:   make(map[string]*ruleState),
186		}
187		return cloneDevice(device), true, nil
188	}
189	
190	// RecordTelemetry stores a live telemetry sample in the device history. The
191	// sample has no caller-supplied eventId, so it is never a replay duplicate; its
192	// observed time is the server receive time.
193	func (s *Store) RecordTelemetry(id string, values map[string]float64) (Device, error) {
194		s.mu.Lock()
195		defer s.mu.Unlock()
196		state, ok := s.devices[id]
197		if !ok {
198			return Device{}, ErrDeviceNotFound
199		}
200		now := s.now().UTC()
201		sequence := int64(len(state.events)) + 1
202		eval := newAlertEvaluator(state)
203		eval.evaluate(sequence, now, values)
204		if s.wal != nil {
205			if err := s.wal.appendRecord(recTelemetry, walTelemetry{
206				DeviceID:   id,
207				Sequence:   sequence,
208				ObservedAt: now,
209				Values:     values,
210				Alerts:     eval.created,
211				Ended:      eval.ended,
212			}); err != nil {
213				return Device{}, storageUnavailable(err)
214			}
215		}
216		state.events = append(state.events, Event{
217			Sequence:   sequence,
218			ObservedAt: now,
219			Values:     cloneTelemetry(values),
220		})
221		state.device.LastSeenAt = now
222		state.device.LastTelemetry = cloneTelemetry(values)
223		eval.commit()
224		return cloneDevice(state.device), nil
225	}
226	
227	// Replay validates and commits a batch atomically. repeat is true when the
228	// batchId was already committed with identical content and the first receipt
229	// is returned unchanged. It returns ErrDeviceNotFound for an unknown device and
230	// ErrBatchConflict when any sample clashes with an existing eventId or the
231	// batchId was previously committed with different ordered content; in either
232	// conflict case no state changes.
233	func (s *Store) Replay(id, batchID string, samples []Sample) (receipt ReplayReceipt, repeat bool, err error) {
234		s.mu.Lock()
235		defer s.mu.Unlock()
236		state, ok := s.devices[id]
237		if !ok {
238			return ReplayReceipt{}, false, ErrDeviceNotFound
239		}
240	
241		if previous, exists := state.batches[batchID]; exists {
242			if !sameOrderedSamples(previous.samples, samples) {
243				return ReplayReceipt{}, false, ErrBatchConflict
244			}
245			return cloneReceipt(previous.receipt), true, nil
246		}
247	
248		// Validate every sample against committed history before appending so a
249		// conflict rolls back without leaving sequences, events or receipts.
250		type plan struct {
251			sample   Sample
252			sequence int64
253			dup      bool
254		}
255		planned := make([]plan, len(samples))
256		nextSequence := int64(len(state.events)) + 1
257		for i, sample := range samples {
258			if sequence, seen := state.byEvent[sample.EventID]; seen {
259				existing := state.events[sequence-1]
260				if !sameInstant(existing.ObservedAt, sample.ObservedAt) ||
261					!sameValues(existing.Values, sample.Values) {
262					return ReplayReceipt{}, false, ErrBatchConflict
263				}
264				planned[i] = plan{sample, sequence, true}
265				continue
266			}
267			planned[i] = plan{sample, nextSequence, false}
268			nextSequence++
269		}
270	
271		// Build the receipt from the plan: only samples that matched a committed
272		// event before this batch are duplicates.
273		receipt = ReplayReceipt{BatchID: batchID, SampleStatus: make([]SampleStatus, 0, len(samples))}
274		for _, entry := range planned {
275			receipt.SampleStatus = append(receipt.SampleStatus, SampleStatus{
276				EventID:   entry.sample.EventID,
277				Sequence:  entry.sequence,
278				Duplicate: entry.dup,
279			})
280			if entry.dup {
281				receipt.Duplicate++
282			} else {
283				receipt.NewCount++
284			}
285		}
286	
287		// Evaluate the batch's new samples against the device's enabled rules, in
288		// array order (which is receive-sequence order). Duplicates never judge,
289		// create, end or refresh alerts. A trigger and a recovery inside one batch
290		// both produce alert changes, all committed together with the batch.
291		eval := newAlertEvaluator(state)
292		for _, entry := range planned {
293			if entry.dup {
294				continue
295			}
296			eval.evaluate(entry.sequence, entry.sample.ObservedAt, entry.sample.Values)
297		}
298	
299		// Durable commit point: the whole batch is one record, synced before any
300		// in-memory state changes and before success is reported. A failure here
301		// leaves sequences, history, receipts, device state and alert changes
302		// untouched.
303		lastNew := -1
304		for i, entry := range planned {
305			if !entry.dup {
306				lastNew = i
307			}
308		}
309		var committedAt time.Time
310		if s.wal != nil {
311			record := walReplay{
312				DeviceID: id,
313				BatchID:  batchID,
314				Samples:  make([]walSample, len(samples)),
315				Receipt:  receipt,
316				Alerts:   eval.created,
317				Ended:    eval.ended,
318			}
319			for i, sample := range samples {
320				record.Samples[i] = walSample{
321					EventID:    sample.EventID,
322					ObservedAt: sample.ObservedAt,
323					Values:     sample.Values,
324				}
325			}
326			if lastNew >= 0 {
327				committedAt = s.now().UTC()
328				record.LastSeenAt = &committedAt
329				record.LastTelemetry = cloneTelemetry(samples[lastNew].Values)
330			}
331			if err := s.wal.appendRecord(recReplay, record); err != nil {
332				return ReplayReceipt{}, false, storageUnavailable(err)
333			}
334		}
335	
336		// Commit: append new samples in array order.
337		for _, entry := range planned {
338			if entry.dup {
339				continue
340			}
341			state.events = append(state.events, Event{
342				Sequence:   entry.sequence,
343				ObservedAt: entry.sample.ObservedAt,
344				Values:     cloneTelemetry(entry.sample.Values),
345			})
346			state.byEvent[entry.sample.EventID] = entry.sequence
347		}
348	
349		committed := make([]Sample, len(samples))
350		copy(committed, samples)
351		for i := range committed {
352			committed[i].Values = cloneTelemetry(samples[i].Values)
353		}
354		state.batches[batchID] = storedBatch{samples: committed, receipt: cloneReceipt(receipt)}
355	
356		if lastNew >= 0 {
357			if s.wal == nil {
358				committedAt = s.now().UTC()
359			}
360			state.device.LastSeenAt = committedAt
361			state.device.LastTelemetry = cloneTelemetry(samples[lastNew].Values)
362		}
363		eval.commit()
364		return receipt, false, nil
365	}
366	
367	func cloneReceipt(receipt ReplayReceipt) ReplayReceipt {
368		receipt.SampleStatus = append([]SampleStatus(nil), receipt.SampleStatus...)
369		return receipt
370	}
371	
372	// --- rules and alerts -------------------------------------------------------
373	
374	// ruleUpdate carries the mutable fields of a rule update. A nil pointer leaves
375	// the field unchanged.
376	type ruleUpdate struct {
377		Metric  *string
378		Trigger *float64
379		Recover *float64
380		Enabled *bool
381	}
382	
383	// AlertFilter narrows an alert listing. An empty string or nil pointer leaves
384	// that dimension unfiltered.
385	type AlertFilter struct {
386		RuleID       string
387		Status       string
388		Acknowledged *bool
389	}
390	
391	// CreateRule registers a new enabled rule on a device. Version starts at 1.
392	// It returns ErrDeviceNotFound for an unknown device and ErrRuleConflict when
393	// the device already has a rule with that id.
394	func (s *Store) CreateRule(id, ruleID, metric string, trigger, recover float64) (Rule, error) {
395		s.mu.Lock()
396		defer s.mu.Unlock()
397		state, ok := s.devices[id]
398		if !ok {
399			return Rule{}, ErrDeviceNotFound
400		}
401		if _, exists := state.rules[ruleID]; exists {
402			return Rule{}, ErrRuleConflict
403		}
404		now := s.now().UTC()
405		rule := Rule{
406			ID: ruleID, Metric: metric, Trigger: trigger, Recover: recover,
407			Enabled: true, Version: 1, CreatedAt: now, UpdatedAt: now,
408		}
409		if s.wal != nil {
410			if err := s.wal.appendRecord(recRule, walRule{DeviceID: id, Rule: rule}); err != nil {
411				return Rule{}, storageUnavailable(err)
412			}
413		}
414		state.rules[ruleID] = &ruleState{rule: rule}
415		return cloneRule(rule), nil
416	}
417	
418	// UpdateRule applies a version-checked optimistic update. A version mismatch
419	// returns ErrVersionConflict with state unchanged. Every successful update
420	// bumps the version by one and immediately ends the rule's active alert (if
421	// any) with reason rule_changed; the rule starts again with no active alert.
422	func (s *Store) UpdateRule(id, ruleID string, update ruleUpdate, version int64) (Rule, []*Alert, error) {
423		s.mu.Lock()
424		defer s.mu.Unlock()
425		state, ok := s.devices[id]
426		if !ok {
427			return Rule{}, nil, ErrDeviceNotFound
428		}
429		rs, ok := state.rules[ruleID]
430		if !ok {
431			return Rule{}, nil, ErrRuleNotFound
432		}
433		if rs.rule.Version != version {
434			return Rule{}, nil, ErrVersionConflict
435		}
436	
437		updated := rs.rule
438		if update.Metric != nil {
439			updated.Metric = *update.Metric
440		}
441		if update.Trigger != nil {
442			updated.Trigger = *update.Trigger
443		}
444		if update.Recover != nil {
445			updated.Recover = *update.Recover
446		}
447		if update.Enabled != nil {
448			updated.Enabled = *update.Enabled
449		}
450		if updated.Recover >= updated.Trigger {
451			return Rule{}, nil, ErrInvalidRule
452		}
453	
454		// End the active alert of the old version before publishing the new one.
455		var ended []*Alert
456		if rs.activeAlertID != 0 {
457			alert := cloneAlert(*state.alerts[rs.activeAlertID-1])
458			alert.Status = alertStatusEnded
459			alert.EndReason = endReasonRuleChanged
460			now := s.now().UTC()
461			alert.EndedAt = &now
462			ended = append(ended, &alert)
463			rs.activeAlertID = 0
464		}
465	
466		updated.Version++
467		updated.UpdatedAt = s.now().UTC()
468	
469		if s.wal != nil {
470			if err := s.wal.appendRecord(recRule, walRule{DeviceID: id, Rule: updated, Ended: ended}); err != nil {
471				return Rule{}, nil, storageUnavailable(err)
472			}
473		}
474		rs.rule = updated
475		for _, alert := range ended {
476			state.alerts[alert.ID-1] = alert
477		}
478		return cloneRule(updated), cloneAlerts(ended), nil
479	}
480	
481	// GetRule returns one rule.
482	func (s *Store) GetRule(id, ruleID string) (Rule, error) {
483		s.mu.RLock()
484		defer s.mu.RUnlock()
485		state, ok := s.devices[id]
486		if !ok {
487			return Rule{}, ErrDeviceNotFound
488		}
489		rs, ok := state.rules[ruleID]
490		if !ok {
491			return Rule{}, ErrRuleNotFound
492		}
493		return cloneRule(rs.rule), nil
494	}
495	
496	// ListRules returns a device's rules, ordered by rule id.
497	func (s *Store) ListRules(id string) ([]Rule, error) {
498		s.mu.RLock()
499		defer s.mu.RUnlock()
500		state, ok := s.devices[id]
501		if !ok {
502			return nil, ErrDeviceNotFound
503		}
504		rules := make([]Rule, 0, len(state.rules))
505		for _, rs := range state.rules {
506			rules = append(rules, cloneRule(rs.rule))
507		}
508		sort.Slice(rules, func(i, j int) bool { return rules[i].ID < rules[j].ID })
509		return rules, nil
510	}
511	
512	// AckAlert records the server time of the first acknowledgment. Repeated
513	// acknowledgments keep the original time and write nothing. It returns
514	// ErrDeviceNotFound for an unknown device and ErrAlertNotFound for an unknown
515	// alert id.
516	func (s *Store) AckAlert(id string, alertID int64) (Alert, error) {
517		s.mu.Lock()
518		defer s.mu.Unlock()
519		state, ok := s.devices[id]
520		if !ok {
521			return Alert{}, ErrDeviceNotFound
522		}
523		if alertID < 1 || int(alertID) > len(state.alerts) {
524			return Alert{}, ErrAlertNotFound
525		}
526		alert := state.alerts[alertID-1]
527		if alert.AcknowledgedAt != nil {
528			return cloneAlert(*alert), nil
529		}
530		now := s.now().UTC()
531		if s.wal != nil {
532			if err := s.wal.appendRecord(recAlertAck, walAlertAck{
533				DeviceID: id, AlertID: alertID, AcknowledgedAt: now,
534			}); err != nil {
535				return Alert{}, storageUnavailable(err)
536			}
537		}
538		alert.AcknowledgedAt = &now
539		return cloneAlert(*alert), nil
540	}
541	
542	// ListAlerts returns a device's alerts with the given filters, ordered by
543	// alert id.
544	func (s *Store) ListAlerts(id string, filter AlertFilter) ([]Alert, error) {
545		s.mu.RLock()
546		defer s.mu.RUnlock()
547		state, ok := s.devices[id]
548		if !ok {
549			return nil, ErrDeviceNotFound
550		}
551		if filter.RuleID != "" {
552			if _, ok := state.rules[filter.RuleID]; !ok {
553				return nil, ErrRuleNotFound
554			}
555		}
556		alerts := make([]Alert, 0, len(state.alerts))
557		for _, alert := range state.alerts {
558			if filter.RuleID != "" && alert.RuleID != filter.RuleID {
559				continue
560			}
561			if filter.Status != "" && alert.Status != filter.Status {
562				continue
563			}
564			if filter.Acknowledged != nil {
565				acknowledged := alert.AcknowledgedAt != nil
566				if *filter.Acknowledged != acknowledged {
567					continue
568				}
569			}
570			alerts = append(alerts, cloneAlert(*alert))
571		}
572		return alerts, nil
573	}
574	
575	// alertEvaluator applies accepted samples to a device's enabled rules without
576	// mutating state until commit. It tracks which rule currently has an active
577	// alert so a trigger and a recovery inside the same batch are both handled in
578	// order.
579	type alertEvaluator struct {
580		state        *deviceState
581		activeByRule map[string]int64 // ruleID -> active alert id (0 when none)
582		created      []*Alert
583		ended        []*Alert
584		nextID       int64
585	}
586	
587	func newAlertEvaluator(state *deviceState) *alertEvaluator {
588		eval := &alertEvaluator{
589			state:        state,
590			activeByRule: make(map[string]int64, len(state.rules)),
591			nextID:       int64(len(state.alerts)) + 1,
592		}
593		for id, rs := range state.rules {
594			eval.activeByRule[id] = rs.activeAlertID
595		}
596		return eval
597	}
598	
599	// evaluate judges one accepted sample. A value at or above the trigger opens
600	// an alert (or keeps the existing one); a value at or below the recovery
601	// threshold ends the active alert; anything in between or a missing metric
602	// leaves state unchanged.
603	func (eval *alertEvaluator) evaluate(seq int64, observedAt time.Time, values map[string]float64) {
604		for _, rs := range eval.state.rules {
605			if !rs.rule.Enabled {
606				continue
607			}
608			value, ok := values[rs.rule.Metric]
609			if !ok {
610				continue
611			}
612			activeID := eval.activeByRule[rs.rule.ID]
613			if value >= rs.rule.Trigger && activeID == 0 {
614				alert := &Alert{
615					ID:                eval.nextID,
616					RuleID:            rs.rule.ID,
617					RuleVersion:       rs.rule.Version,
618					Metric:            rs.rule.Metric,
619					Trigger:           rs.rule.Trigger,
620					Recover:           rs.rule.Recover,
621					Status:            alertStatusActive,
622					TriggerSequence:   seq,
623					TriggerValue:      value,
624					TriggerObservedAt: observedAt,
625				}
626				eval.nextID++
627				eval.created = append(eval.created, alert)
628				eval.activeByRule[rs.rule.ID] = alert.ID
629			} else if value <= rs.rule.Recover && activeID != 0 {
630				var source *Alert
631				if activeID <= int64(len(eval.state.alerts)) {
632					source = eval.state.alerts[activeID-1]
633				} else {
634					source = eval.created[activeID-int64(len(eval.state.alerts))-1]
635				}
636				alert := cloneAlert(*source)
637				alert.Status = alertStatusEnded
638				alert.EndReason = endReasonRecovered
639				alert.RecoverSequence = &seq
640				alert.RecoverValue = &value
641				alert.RecoverObservedAt = &observedAt
642				eval.ended = append(eval.ended, &alert)
643				eval.activeByRule[rs.rule.ID] = 0
644			}
645		}
646	}
647	
648	// commit publishes the planned alert changes to the device state.
649	func (eval *alertEvaluator) commit() {
650		applyAlertChanges(eval.state, eval.created, eval.ended)
651	}
652	
653	// applyAlertChanges appends created alerts and replaces ended ones, keeping
654	// each rule's active-alert pointer in sync. It is shared by live evaluation
655	// and WAL recovery.
656	func applyAlertChanges(state *deviceState, created, ended []*Alert) {
657		for _, alert := range created {
658			state.alerts = append(state.alerts, alert)
659			if rs, ok := state.rules[alert.RuleID]; ok {
660				rs.activeAlertID = alert.ID
661			}
662		}
663		for _, alert := range ended {
664			state.alerts[alert.ID-1] = alert
665			if rs, ok := state.rules[alert.RuleID]; ok && rs.activeAlertID == alert.ID {
666				rs.activeAlertID = 0
667			}
668		}
669	}
670	
671	func cloneRule(rule Rule) Rule {
672		return rule
673	}
674	
675	func cloneAlert(alert Alert) Alert {
676		if alert.RecoverSequence != nil {
677			seq := *alert.RecoverSequence
678			alert.RecoverSequence = &seq
679		}
680		if alert.RecoverValue != nil {
681			value := *alert.RecoverValue
682			alert.RecoverValue = &value
683		}
684		if alert.RecoverObservedAt != nil {
685			t := *alert.RecoverObservedAt
686			alert.RecoverObservedAt = &t
687		}
688		if alert.EndedAt != nil {
689			t := *alert.EndedAt
690			alert.EndedAt = &t
691		}
692		if alert.AcknowledgedAt != nil {
693			t := *alert.AcknowledgedAt
694			alert.AcknowledgedAt = &t
695		}
696		return alert
697	}
698	
699	func cloneAlerts(alerts []*Alert) []*Alert {
700		if alerts == nil {
701			return nil
702		}
703		cloned := make([]*Alert, len(alerts))
704		for i, alert := range alerts {
705			c := cloneAlert(*alert)
706			cloned[i] = &c
707		}
708		return cloned
709	}
710	
711	// History returns one page of a device's event history. afterIndex is the first
712	// 0-based event slot to scan (0 for the first page); limit caps the number of
713	// matching events returned. bound pins the scan to sequences no larger than
714	// bound; a zero bound means "current maximum", which is then returned so
715	// callers can pin subsequent pages. nextIndex is the slot a following page
716	// should start at when hasMore is true. Concurrent writes therefore cannot
717	// skip or duplicate rows within a paged walk.
718	func (s *Store) History(id string, filter HistoryFilter, afterIndex, bound int64, limit int) (events []Event, appliedBound, nextIndex int64, hasMore bool, err error) {
719		s.mu.RLock()
720		defer s.mu.RUnlock()
721		state, ok := s.devices[id]
722		if !ok {
723			return nil, 0, 0, false, ErrDeviceNotFound
724		}
725		highWater := int64(len(state.events))
726		if bound == 0 {
727			bound = highWater
728		}
729		events = make([]Event, 0, limit)
730		for index := afterIndex; index < bound; index++ {
731			event := state.events[index]
732			if !filter.From.IsZero() && event.ObservedAt.Before(filter.From) {
733				continue
734			}
735			if !filter.To.IsZero() && event.ObservedAt.After(filter.To) {
736				continue
737			}
738			if len(events) < limit {
739				events = append(events, cloneEvent(event))
740				continue
741			}
742			// This match belongs to the next page; resume scanning here so rows in
743			// the gap are never examined twice.
744			return events, bound, index, true, nil
745		}
746		return events, bound, bound, false, nil
747	}
748	
749	func (s *Store) Snapshot() []Device {
750		s.mu.RLock()
751		defer s.mu.RUnlock()
752		result := make([]Device, 0, len(s.devices))
753		for _, state := range s.devices {
754			result = append(result, cloneDevice(state.device))
755		}
756		sort.Slice(result, func(i, j int) bool { return result[i].ID < result[j].ID })
757		return result
758	}
759	
760	func cloneDevice(device Device) Device {
761		device.LastTelemetry = cloneTelemetry(device.LastTelemetry)
762		return device
763	}
764	
765	func cloneEvent(event Event) Event {
766		event.Values = cloneTelemetry(event.Values)
767		return event
768	}
769	
770	func cloneTelemetry(values map[string]float64) map[string]float64 {
771		if values == nil {
772			return nil
773		}
774		cloned := make(map[string]float64, len(values))
775		for key, value := range values {
776			cloned[key] = value
777		}
778		return cloned
779	}
780	
781	// sameInstant compares times as UTC instants.
782	func sameInstant(a, b time.Time) bool {
783		return a.UTC().Equal(b.UTC())
784	}
785	
786	// sameValues compares metric maps by key and value.
787	func sameValues(a, b map[string]float64) bool {
788		if len(a) != len(b) {
789			return false
790		}
791		for key, value := range a {
792			other, ok := b[key]
793			if !ok || value != other {
794				return false
795			}
796		}
797		return true
798	}
799	
800	// sameOrderedSamples reports whether two batches carry the same samples in the
801	// same order, compared as UTC instants and key/value maps.
802	func sameOrderedSamples(a, b []Sample) bool {
803		if len(a) != len(b) {
804			return false
805		}
806		for i := range a {
807			if a[i].EventID != b[i].EventID ||
808				!sameInstant(a[i].ObservedAt, b[i].ObservedAt) ||
809				!sameValues(a[i].Values, b[i].Values) {
810				return false
811			}
812		}
813		return true
814	}
815

