278		}
279		if err := decodeJSON(r, &request); err != nil {
280			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "request body must be a single valid JSON object"})
281			return
282		}
283		ruleID := strings.TrimSpace(request.ID)
284		metric := strings.TrimSpace(request.Metric)
285		if ruleID == "" {
286			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "id is required"})
287			return
288		}
289		if metric == "" {
290			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "metric is required"})
291			return
292		}
293		if !finiteFloat(request.Trigger) || !finiteFloat(request.Recover) {
294			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "thresholds must be finite numbers"})
295			return
296		}
297		if request.Recover >= request.Trigger {
298			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "recover threshold must be less than trigger threshold"})
299			return
300		}
301		rule, err := h.store.CreateRule(r.PathValue("id"), ruleID, metric, request.Trigger, request.Recover)
302		if errors.Is(err, ErrDeviceNotFound) {
303			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
304			return
305		}
306		if errors.Is(err, ErrRuleConflict) {
307			writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
308			return
309		}
310		if errors.Is(err, ErrStorageUnavailable) {
311			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
312			return
313		}
314		if err != nil {
315			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
316			return
317		}
318		writeJSON(w, http.StatusCreated, rule)
319	}
320	
321	func (h *handler) listRules(w http.ResponseWriter, r *http.Request) {
322		rules, err := h.store.ListRules(r.PathValue("id"))
323		if errors.Is(err, ErrDeviceNotFound) {
324			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
325			return
326		}
327		if err != nil {
328			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
329			return
330		}
331		writeJSON(w, http.StatusOK, map[string]any{"rules": rules})
332	}
333	
334	func (h *handler) getRule(w http.ResponseWriter, r *http.Request) {
335		rule, err := h.store.GetRule(r.PathValue("id"), r.PathValue("ruleId"))
336		if errors.Is(err, ErrDeviceNotFound) {
337			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
338			return
339		}
340		if errors.Is(err, ErrRuleNotFound) {
341			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
342			return
343		}
344		if err != nil {
345			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
346			return
347		}
348		writeJSON(w, http.StatusOK, rule)
349	}
350	
351	func (h *handler) updateRule(w http.ResponseWriter, r *http.Request) {
352		var request struct {
353			Metric  *string  `json:"metric"`
354			Trigger *float64 `json:"trigger"`
355			Recover *float64 `json:"recover"`
356			Enabled *bool    `json:"enabled"`
357			Version int64    `json:"version"`
358		}
359		if err := decodeJSON(r, &request); err != nil {
360			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "request body must be a single valid JSON object"})
361			return
362		}
363		if request.Version < 1 {
364			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "version is required"})
365			return
366		}
367		if request.Metric != nil && strings.TrimSpace(*request.Metric) == "" {
368			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "metric must not be blank"})
369			return
370		}
371		if request.Trigger != nil && !finiteFloat(*request.Trigger) {
372			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "trigger must be a finite number"})
373			return
374		}
375		if request.Recover != nil && !finiteFloat(*request.Recover) {
376			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "recover must be a finite number"})
377			return
378		}
379		update := ruleUpdate{}
380		if request.Metric != nil {
381			metric := strings.TrimSpace(*request.Metric)
382			update.Metric = &metric
383		}
384		if request.Trigger != nil {
385			update.Trigger = request.Trigger
386		}
387		if request.Recover != nil {
388			update.Recover = request.Recover
389		}
390		if request.Enabled != nil {
391			update.Enabled = request.Enabled
392		}
393		rule, _, err := h.store.UpdateRule(r.PathValue("id"), r.PathValue("ruleId"), update, request.Version)
394		if errors.Is(err, ErrDeviceNotFound) || errors.Is(err, ErrRuleNotFound) {
395			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
396			return
397		}
398		if errors.Is(err, ErrVersionConflict) {
399			writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
400			return
401		}
402		if errors.Is(err, ErrInvalidRule) {
403			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "recover threshold must be less than trigger threshold"})
404			return
405		}
406		if errors.Is(err, ErrStorageUnavailable) {
407			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
408			return
409		}
410		if err != nil {
411			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
412			return
413		}
414		writeJSON(w, http.StatusOK, rule)
415	}
416	
417	// --- alerts -----------------------------------------------------------------
418	
419	func (h *handler) listAlerts(w http.ResponseWriter, r *http.Request) {
420		query := r.URL.Query()
421		filter := AlertFilter{RuleID: strings.TrimSpace(query.Get("ruleId"))}
422		if raw := strings.TrimSpace(query.Get("status")); raw != "" {
423			if raw != alertStatusActive && raw != alertStatusEnded {
424				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "status must be active or ended"})
425				return
426			}
427			filter.Status = raw
428		}
429		if raw := strings.TrimSpace(query.Get("acknowledged")); raw != "" {
430			switch raw {
431			case "true", "1":
432				v := true
433				filter.Acknowledged = &v
434			case "false", "0":
435				v := false
436				filter.Acknowledged = &v
437			default:
438				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "acknowledged must be true or false"})
439				return
440			}
441		}
442		alerts, err := h.store.ListAlerts(r.PathValue("id"), filter)
443		if errors.Is(err, ErrDeviceNotFound) {
444			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
445			return
446		}
447		if errors.Is(err, ErrRuleNotFound) {
448			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
449			return
450		}
451		if err != nil {
452			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
453			return
454		}
455		writeJSON(w, http.StatusOK, map[string]any{"alerts": alerts})
456	}
457	
458	func (h *handler) ackAlert(w http.ResponseWriter, r *http.Request) {
459		alertID, err := strconv.ParseInt(r.PathValue("alertId"), 10, 64)
460		if err != nil || alertID < 1 {
461			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "alertId must be a positive integer"})
462			return
463		}
464		alert, err := h.store.AckAlert(r.PathValue("id"), alertID)
465		if errors.Is(err, ErrDeviceNotFound) || errors.Is(err, ErrAlertNotFound) {
466			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
467			return
468		}
469		if errors.Is(err, ErrStorageUnavailable) {
470			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
471			return
472		}
473		if err != nil {
474			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
475			return
476		}
477		writeJSON(w, http.StatusOK, alert)
478	}
479	
480	func finiteFloat(value float64) bool {
481		return !math.IsNaN(value) && !math.IsInf(value, 0)
482	}
483	
484	func hasBlankKey(values map[string]float64) bool {
485		for key := range values {
486			if strings.TrimSpace(key) == "" {
487				return true
488			}
489		}
490		return false
491	}
492	
493	func finiteValues(values map[string]float64) bool {
494		for _, value := range values {
495			if math.IsNaN(value) || math.IsInf(value, 0) {
496				return false
497			}
498		}
499		return true
500	}
501	
502	func decodeJSON(r *http.Request, target any) error {
503		decoder := json.NewDecoder(http.MaxBytesReader(nil, r.Body, 1<<20))
504		decoder.DisallowUnknownFields()
505		return decoder.Decode(target)
506	}
507	
508	// decodeSingleJSON requires the body to be exactly one JSON value, rejecting
509	// trailing data such as a second JSON object or concatenated documents.
510	func decodeSingleJSON(r *http.Request, target any) error {
511		decoder := json.NewDecoder(http.MaxBytesReader(nil, r.Body, 1<<20))
512		decoder.DisallowUnknownFields()
513		if err := decoder.Decode(target); err != nil {
514			return err
515		}
516		var trailing any
517		if err := decoder.Decode(&trailing); !errors.Is(err, io.EOF) {
518			return errors.New("body must contain a single JSON value")
519		}
520		return nil
521	}
522	
523	func writeJSON(w http.ResponseWriter, status int, value any) {
524		w.Header().Set("Content-Type", "application/json")
525		w.WriteHeader(status)
526		_ = json.NewEncoder(w).Encode(value)
527	}
