536	func walHeader() []byte {
537		header := make([]byte, headerLen)
538		copy(header[0:8], walMagic)
539		binary.LittleEndian.PutUint32(header[8:12], walVersion)
540		return header
541	}
542	
543	// marshalFrame frames one record as
544	// [length uint32 LE][type byte][payload][crc32 LE].
545	// The CRC covers length, type and payload, so even a damaged length field of
546	// the final frame fails verification instead of masquerading as a torn tail.
547	func marshalFrame(recType byte, value any) ([]byte, error) {
548		payload, err := json.Marshal(value)
549		if err != nil {
550			return nil, err
551		}
552		if len(payload) > maxRecordPayload {
553			return nil, fmt.Errorf("wal record too large: %d bytes", len(payload))
554		}
555		frame := make([]byte, 5+len(payload)+4)
556		binary.LittleEndian.PutUint32(frame[0:4], uint32(len(payload)))
557		frame[4] = recType
558		copy(frame[5:], payload)
559		binary.LittleEndian.PutUint32(frame[5+len(payload):], crc32.Checksum(frame[:5+len(payload)], crcTable))
560		return frame, nil
561	}
