563	// applyAlertRecord validates and applies the alert changes carried by a
564	// telemetry or replay record. It rejects relational inconsistency so a damaged
565	// WAL fails startup rather than producing broken alert state.
566	func applyAlertRecord(state *deviceState, created, ended []*Alert) error {
567		wantID := int64(len(state.alerts)) + 1
568		for _, alert := range created {
569			if alert == nil {
570				return errors.New("alert record contains a null create")
571			}
572			if alert.ID != wantID {
573				return fmt.Errorf("alert create id mismatch: got %d, want %d", alert.ID, wantID)
574			}
575			if alert.Status != alertStatusActive || alert.RuleID == "" || alert.Metric == "" ||
576				alert.TriggerSequence <= 0 || alert.TriggerObservedAt.IsZero() {
577				return fmt.Errorf("alert %d create is incomplete", alert.ID)
578			}
579			wantID++
580		}
581		maxID := int64(len(state.alerts) + len(created))
582		for _, alert := range ended {
583			if alert == nil {
584				return errors.New("alert record contains a null end")
585			}
586			if alert.ID < 1 || alert.ID > maxID {
587				return fmt.Errorf("alert end id %d out of range (1..%d)", alert.ID, maxID)
588			}
589			if alert.Status != alertStatusEnded || alert.EndReason != endReasonRecovered {
590				return fmt.Errorf("alert %d end is malformed", alert.ID)
591			}
592		}
593		applyAlertChanges(state, created, ended)
594		return nil
595	}
