597	// applyRecord rebuilds in-memory state from one committed record, rejecting
598	// any structural or relational inconsistency. It never calls the clock, so
599	// recovery cannot refresh device timestamps.
600	func applyRecord(s *Store, recType byte, payload []byte) error {
601		switch recType {
602		case recRegister:
603			var rec walRegister
604			if err := json.Unmarshal(payload, &rec); err != nil {
605				return fmt.Errorf("invalid register record: %w", err)
606			}
607			if rec.ID == "" || rec.RegisteredAt.IsZero() || rec.LastSeenAt.IsZero() {
608				return errors.New("register record missing fields")
609			}
610			if _, exists := s.devices[rec.ID]; exists {
611				return fmt.Errorf("duplicate registration for device %q", rec.ID)
612			}
613			s.devices[rec.ID] = &deviceState{
614				device: Device{
615					ID:           rec.ID,
616					Site:         rec.Site,
617					RegisteredAt: rec.RegisteredAt.UTC(),
618					LastSeenAt:   rec.LastSeenAt.UTC(),
619				},
620				byEvent: make(map[string]int64),
621				batches: make(map[string]storedBatch),
622				rules:   make(map[string]*ruleState),
623			}
624			return nil
625	
626		case recTelemetry:
627			var rec walTelemetry
628			if err := json.Unmarshal(payload, &rec); err != nil {
629				return fmt.Errorf("invalid telemetry record: %w", err)
630			}
631			state, ok := s.devices[rec.DeviceID]
632			if !ok {
633				return fmt.Errorf("telemetry for unknown device %q", rec.DeviceID)
634			}
635			if rec.Sequence != int64(len(state.events))+1 {
636				return fmt.Errorf("device %q telemetry sequence gap: got %d, want %d", rec.DeviceID, rec.Sequence, len(state.events)+1)
637			}
638			if rec.ObservedAt.IsZero() || len(rec.Values) == 0 {
639				return fmt.Errorf("device %q telemetry record missing fields", rec.DeviceID)
640			}
641			state.events = append(state.events, Event{
642				Sequence:   rec.Sequence,
643				ObservedAt: rec.ObservedAt.UTC(),
644				Values:     cloneTelemetry(rec.Values),
645			})
646			state.device.LastSeenAt = rec.ObservedAt.UTC()
647			state.device.LastTelemetry = cloneTelemetry(rec.Values)
648			if err := applyAlertRecord(state, rec.Alerts, rec.Ended); err != nil {
649				return err
650			}
651			return nil
652	
653		case recReplay:
654			var rec walReplay
655			if err := json.Unmarshal(payload, &rec); err != nil {
656				return fmt.Errorf("invalid replay record: %w", err)
657			}
658			state, ok := s.devices[rec.DeviceID]
659			if !ok {
660				return fmt.Errorf("replay for unknown device %q", rec.DeviceID)
661			}
662			if rec.BatchID == "" || len(rec.Samples) == 0 || len(rec.Samples) != len(rec.Receipt.SampleStatus) {
663				return fmt.Errorf("device %q replay record is incomplete", rec.DeviceID)
664			}
665			if rec.Receipt.BatchID != rec.BatchID {
666				return fmt.Errorf("device %q receipt batchId %q does not match %q", rec.DeviceID, rec.Receipt.BatchID, rec.BatchID)
667			}
668			if _, exists := state.batches[rec.BatchID]; exists {
669				return fmt.Errorf("device %q duplicate stored receipt for batch %q", rec.DeviceID, rec.BatchID)
670			}
671	
672			samples := make([]Sample, len(rec.Samples))
673			newCount, dupCount := 0, 0
674			lastNew := -1
675			for i, entry := range rec.Samples {
676				status := rec.Receipt.SampleStatus[i]
677				if entry.EventID == "" || entry.ObservedAt.IsZero() || len(entry.Values) == 0 {
678					return fmt.Errorf("device %q batch %q sample %d is incomplete", rec.DeviceID, rec.BatchID, i)
679				}
680				if status.EventID != entry.EventID {
681					return fmt.Errorf("device %q batch %q receipt/sample eventId mismatch at %d", rec.DeviceID, rec.BatchID, i)
682				}
683				samples[i] = Sample{
684					EventID:    entry.EventID,
685					ObservedAt: entry.ObservedAt.UTC(),
686					Values:     cloneTelemetry(entry.Values),
687				}
688				if sequence, seen := state.byEvent[entry.EventID]; seen {
689					existing := state.events[sequence-1]
690					if !sameInstant(existing.ObservedAt, entry.ObservedAt) || !sameValues(existing.Values, entry.Values) {
691						return fmt.Errorf("device %q dedupe record for %q disagrees with history", rec.DeviceID, entry.EventID)
692					}
693					if !status.Duplicate || status.Sequence != sequence {
694						return fmt.Errorf("device %q receipt for %q should reuse sequence %d", rec.DeviceID, entry.EventID, sequence)
695					}
696					dupCount++
697					continue
698				}
699				if status.Duplicate {
700					return fmt.Errorf("device %q receipt marks unseen event %q as duplicate", rec.DeviceID, entry.EventID)
701				}
702				want := int64(len(state.events)) + 1
703				if status.Sequence != want {
704					return fmt.Errorf("device %q batch %q sequence mismatch for %q: got %d, want %d", rec.DeviceID, rec.BatchID, entry.EventID, status.Sequence, want)
705				}
706				state.events = append(state.events, Event{
707					Sequence:   status.Sequence,
708					ObservedAt: entry.ObservedAt.UTC(),
709					Values:     cloneTelemetry(entry.Values),
710				})
711				state.byEvent[entry.EventID] = status.Sequence
712				newCount++
713				lastNew = i
714			}
715			if rec.Receipt.NewCount != newCount || rec.Receipt.Duplicate != dupCount {
716				return fmt.Errorf("device %q batch %q receipt counts disagree with samples (%d/%d vs %d/%d)",
717					rec.DeviceID, rec.BatchID, rec.Receipt.NewCount, rec.Receipt.Duplicate, newCount, dupCount)
718			}
719	
720			if newCount > 0 {
721				if rec.LastSeenAt == nil || rec.LastSeenAt.IsZero() {
722					return fmt.Errorf("device %q batch %q missing recorded receive time", rec.DeviceID, rec.BatchID)
723				}
724				if !sameValues(rec.LastTelemetry, samples[lastNew].Values) {
725					return fmt.Errorf("device %q batch %q last telemetry disagrees with last new sample", rec.DeviceID, rec.BatchID)
726				}
727				state.device.LastSeenAt = rec.LastSeenAt.UTC()
728				state.device.LastTelemetry = cloneTelemetry(rec.LastTelemetry)
729			} else if rec.LastSeenAt != nil || len(rec.LastTelemetry) != 0 {
730				return fmt.Errorf("device %q all-duplicate batch %q unexpectedly refreshed device state", rec.DeviceID, rec.BatchID)
731			}
732	
733			state.batches[rec.BatchID] = storedBatch{samples: samples, receipt: cloneReceipt(rec.Receipt)}
734			if err := applyAlertRecord(state, rec.Alerts, rec.Ended); err != nil {
735				return err
736			}
737			return nil
738	
739		case recRule:
740			var rec walRule
741			if err := json.Unmarshal(payload, &rec); err != nil {
742				return fmt.Errorf("invalid rule record: %w", err)
743			}
744			state, ok := s.devices[rec.DeviceID]
745			if !ok {
746				return fmt.Errorf("rule for unknown device %q", rec.DeviceID)
747			}
748			if rec.Rule.ID == "" || rec.Rule.Metric == "" || rec.Rule.Version < 1 ||
749				rec.Rule.CreatedAt.IsZero() || rec.Rule.UpdatedAt.IsZero() {
750				return fmt.Errorf("device %q rule record is incomplete", rec.DeviceID)
751			}
752			if existing, exists := state.rules[rec.Rule.ID]; exists {
753				if existing.rule.Version != rec.Rule.Version-1 {
754					return fmt.Errorf("device %q rule %q version gap: got %d, want %d",
755						rec.DeviceID, rec.Rule.ID, rec.Rule.Version, existing.rule.Version+1)
756				}
757				existing.rule = rec.Rule
758			} else {
759				if rec.Rule.Version != 1 {
760					return fmt.Errorf("device %q rule %q first record has version %d, want 1",
761						rec.DeviceID, rec.Rule.ID, rec.Rule.Version)
762				}
763				state.rules[rec.Rule.ID] = &ruleState{rule: rec.Rule}
764			}
765			for _, alert := range rec.Ended {
766				if alert == nil || alert.ID < 1 || int(alert.ID) > len(state.alerts) {
767					return fmt.Errorf("device %q rule %q ends unknown alert", rec.DeviceID, rec.Rule.ID)
768				}
769				if alert.Status != alertStatusEnded || alert.EndReason != endReasonRuleChanged || alert.EndedAt == nil {
770					return fmt.Errorf("device %q rule %q end of alert %d is malformed", rec.DeviceID, rec.Rule.ID, alert.ID)
771				}
772				state.alerts[alert.ID-1] = alert
773				if rs, ok := state.rules[alert.RuleID]; ok && rs.activeAlertID == alert.ID {
774					rs.activeAlertID = 0
775				}
776			}
777			return nil
778	
779		case recAlertAck:
780			var rec walAlertAck
781			if err := json.Unmarshal(payload, &rec); err != nil {
782				return fmt.Errorf("invalid alert ack record: %w", err)
783			}
784			state, ok := s.devices[rec.DeviceID]
785			if !ok {
786				return fmt.Errorf("alert ack for unknown device %q", rec.DeviceID)
787			}
788			if rec.AlertID < 1 || int(rec.AlertID) > len(state.alerts) {
789				return fmt.Errorf("device %q ack for unknown alert %d", rec.DeviceID, rec.AlertID)
790			}
791			if rec.AcknowledgedAt.IsZero() {
792				return fmt.Errorf("device %q ack for alert %d missing time", rec.DeviceID, rec.AlertID)
793			}
794			alert := state.alerts[rec.AlertID-1]
795			if alert.AcknowledgedAt == nil {
796				t := rec.AcknowledgedAt.UTC()
797				alert.AcknowledgedAt = &t
798			}
799			return nil
800	
801		case recConfigPublish:
802			var rec walConfigPublish
803			if err := json.Unmarshal(payload, &rec); err != nil {
804				return fmt.Errorf("invalid config publish record: %w", err)
805			}
806			state, ok := s.devices[rec.DeviceID]
807			if !ok {
808				return fmt.Errorf("config publish for unknown device %q", rec.DeviceID)
809			}
810			if rec.RequestID == "" || rec.PublishedAt.IsZero() {
811				return fmt.Errorf("device %q config publish record is incomplete", rec.DeviceID)
812			}
813			if !isNonEmptyJSONObject(rec.Content) {
814				return fmt.Errorf("device %q config v%d content is not a non-empty JSON object", rec.DeviceID, rec.Version)
815			}
816			if state.config == nil {
817				state.config = newConfigState()
818			}
819			cfg := state.config
820			if rec.Version != int64(len(cfg.versions))+1 {
821				return fmt.Errorf("device %q config version gap: got %d, want %d",
822					rec.DeviceID, rec.Version, len(cfg.versions)+1)
823			}
824			if rec.BaseVersion != rec.Version-1 {
825				return fmt.Errorf("device %q config v%d base %d does not precede version",
826					rec.DeviceID, rec.Version, rec.BaseVersion)
827			}
828			if _, dup := cfg.publishes[rec.RequestID]; dup {
829				return fmt.Errorf("device %q duplicate config publish request %q", rec.DeviceID, rec.RequestID)
830			}
831			if rec.Version <= cfg.applied {
832				return fmt.Errorf("device %q config v%d published after applied %d", rec.DeviceID, rec.Version, cfg.applied)
833			}
834			content := cloneJSON(rec.Content)
835			cfg.versions = append(cfg.versions, publishedConfig{
836				content:     content,
837				publishedAt: rec.PublishedAt.UTC(),
838			})
839			cfg.publishes[rec.RequestID] = storedPublish{
840				baseVersion: rec.BaseVersion,
841				content:     cloneJSON(content),
842				result: ConfigPublishResult{
843					RequestID:   rec.RequestID,
844					Version:     rec.Version,
845					Content:     cloneJSON(content),
846					PublishedAt: rec.PublishedAt.UTC(),
847				},
848			}
849			return nil
850	
851		case recConfigReceipt:
852			var rec walConfigReceipt
853			if err := json.Unmarshal(payload, &rec); err != nil {
854				return fmt.Errorf("invalid config receipt record: %w", err)
855			}
856			state, ok := s.devices[rec.DeviceID]
857			if !ok {
858				return fmt.Errorf("config receipt for unknown device %q", rec.DeviceID)
859			}
860			if rec.ReceiptID == "" || rec.ReceivedAt.IsZero() {
861				return fmt.Errorf("device %q config receipt record is incomplete", rec.DeviceID)
862			}
863			if !rec.Success && strings.TrimSpace(rec.Reason) == "" {
864				return fmt.Errorf("device %q config receipt %q fails without a reason", rec.DeviceID, rec.ReceiptID)
865			}
866			if state.config == nil {
867				state.config = newConfigState()
868			}
869			cfg := state.config
870			if rec.Version < 1 || rec.Version > int64(len(cfg.versions)) {
871				return fmt.Errorf("device %q config receipt %q for unknown version %d", rec.DeviceID, rec.ReceiptID, rec.Version)
872			}
873			if _, dup := cfg.byReceipt[rec.ReceiptID]; dup {
874				return fmt.Errorf("device %q duplicate config receipt %q", rec.DeviceID, rec.ReceiptID)
875			}
876			if rec.Version < cfg.applied {
877				return fmt.Errorf("device %q config receipt %q version %d is below applied %d",
878					rec.DeviceID, rec.ReceiptID, rec.Version, cfg.applied)
879			}
880			if !rec.Success && rec.Version <= cfg.applied {
881				return fmt.Errorf("device %q config receipt %q fails an already applied version %d",
882					rec.DeviceID, rec.ReceiptID, rec.Version)
883			}
884			receipt := ConfigReceipt{
885				ReceiptID:  rec.ReceiptID,
886				Version:    rec.Version,
887				Success:    rec.Success,
888				Reason:     rec.Reason,
889				ReceivedAt: rec.ReceivedAt.UTC(),
890			}
891			cfg.receipts = append(cfg.receipts, receipt)
892			cfg.byReceipt[rec.ReceiptID] = receipt
893			if rec.Success && rec.Version > cfg.applied {
894				cfg.applied = rec.Version
895			}
896			return nil
897	
898		case recTaskCreate:
899			var rec walTaskCreate
900			if err := json.Unmarshal(payload, &rec); err != nil {
901				return fmt.Errorf("invalid task create record: %w", err)
902			}
903			state, ok := s.devices[rec.DeviceID]
904			if !ok {
905				return fmt.Errorf("task create for unknown device %q", rec.DeviceID)
906			}
907			if rec.RequestID == "" || rec.DurationSeconds < 1 || rec.DurationSeconds > taskMaxDuration || rec.CreatedAt.IsZero() {
908				return fmt.Errorf("device %q task create record is incomplete", rec.DeviceID)
909			}
910			state.ensureTasks()
911			if _, dup := state.tasksByRequest[rec.RequestID]; dup {
912				return fmt.Errorf("device %q duplicate task request %q", rec.DeviceID, rec.RequestID)
913			}
914			if rec.TaskID != int64(len(state.tasks))+1 {
915				return fmt.Errorf("device %q task id gap: got %d, want %d", rec.DeviceID, rec.TaskID, len(state.tasks)+1)
916			}
917			task := DiagnosticTask{
918				ID:              rec.TaskID,
919				RequestID:       rec.RequestID,
920				DurationSeconds: rec.DurationSeconds,
921				Status:          taskStatusPending,
922				CreatedAt:       rec.CreatedAt.UTC(),
923				NextClaimableAt: rec.NextClaimableAt.UTC(),
924			}
925			ts := &taskState{task: task, reports: make(map[string]storedReport)}
926			rec.Audit.Seq = 1
927			ts.audit = append(ts.audit, rec.Audit)
928			state.tasks = append(state.tasks, ts)
929			state.tasksByRequest[rec.RequestID] = ts
930			return nil
931	
932		case recTaskClaim:
933			var rec walTaskClaim
934			if err := json.Unmarshal(payload, &rec); err != nil {
935				return fmt.Errorf("invalid task claim record: %w", err)
936			}
937			state, ok := s.devices[rec.DeviceID]
938			if !ok {
939				return fmt.Errorf("task claim for unknown device %q", rec.DeviceID)
940			}
941			ts := findTask(state, rec.TaskID)
942			if ts == nil {
943				return fmt.Errorf("device %q claim for unknown task %d", rec.DeviceID, rec.TaskID)
944			}
945			if ts.task.Status != taskStatusPending && ts.task.Status != taskStatusWaiting {
946				return fmt.Errorf("device %q task %d claim in bad state %q", rec.DeviceID, rec.TaskID, ts.task.Status)
947			}
948			if ts.task.Attempts != rec.Attempt-1 {
949				return fmt.Errorf("device %q task %d attempt gap: got %d, want %d", rec.DeviceID, rec.TaskID, rec.Attempt, ts.task.Attempts+1)
950			}
951			if rec.Credential == "" || rec.ClaimedAt.IsZero() || rec.Deadline.IsZero() {
952				return fmt.Errorf("device %q task %d claim record is incomplete", rec.DeviceID, rec.TaskID)
953			}
954			ts.task.Status = taskStatusInProgress
955			ts.task.Attempts = rec.Attempt
956			ts.task.Credential = rec.Credential
957			claimedAt := rec.ClaimedAt.UTC()
958			ts.task.ClaimedAt = &claimedAt
959			deadline := rec.Deadline.UTC()
960			ts.task.Deadline = &deadline
961			ts.task.NextClaimableAt = time.Time{}
962			rec.Audit.Seq = int64(len(ts.audit)) + 1
963			ts.audit = append(ts.audit, rec.Audit)
964			return nil
965	
966		case recTaskReport:
967			var rec walTaskReport
968			if err := json.Unmarshal(payload, &rec); err != nil {
969				return fmt.Errorf("invalid task report record: %w", err)
970			}
971			state, ok := s.devices[rec.DeviceID]
972			if !ok {
973				return fmt.Errorf("task report for unknown device %q", rec.DeviceID)
974			}
975			ts := findTask(state, rec.TaskID)
976			if ts == nil {
977				return fmt.Errorf("device %q report for unknown task %d", rec.DeviceID, rec.TaskID)
978			}
979			if ts.task.Status != taskStatusInProgress {
980				return fmt.Errorf("device %q task %d report in bad state %q", rec.DeviceID, rec.TaskID, ts.task.Status)
981			}
982			if rec.ReceiptID == "" || rec.ReceivedAt.IsZero() {
983				return fmt.Errorf("device %q task report record is incomplete", rec.DeviceID)
984			}
985			if _, dup := ts.reports[rec.ReceiptID]; dup {
986				return fmt.Errorf("device %q duplicate task report receipt %q", rec.DeviceID, rec.ReceiptID)
987			}
988			if !rec.Success && strings.TrimSpace(rec.Reason) == "" {
989				return fmt.Errorf("device %q task report %q fails without a reason", rec.DeviceID, rec.ReceiptID)
990			}
991			if rec.Success && !isJSONObject(rec.Result) {
992				return fmt.Errorf("device %q task report %q success lacks an object result", rec.DeviceID, rec.ReceiptID)
993			}
994			if rec.Status != taskStatusSucceeded && rec.Status != taskStatusWaiting && rec.Status != taskStatusFailed {
995				return fmt.Errorf("device %q task %d report has bad resulting status %q", rec.DeviceID, rec.TaskID, rec.Status)
996			}
997			ts.task.Status = rec.Status
998			ts.task.Failures = rec.Failures
999			ts.task.NextClaimableAt = rec.NextClaimableAt.UTC()
1000			ts.task.FailureReason = rec.FailureReason
1001			if rec.CompletedAt != nil {
1002				t := rec.CompletedAt.UTC()
1003				ts.task.CompletedAt = &t
1004			}
1005			if rec.Success {
1006				ts.task.Result = cloneJSON(rec.Result)
1007			}
1008			ts.task.Credential = ""
1009			ts.task.ClaimedAt = nil
1010			ts.task.Deadline = nil
1011			report := storedReport{
1012				receiptID:  rec.ReceiptID,
1013				success:    rec.Success,
1014				reason:     rec.Reason,
1015				result:     cloneJSON(rec.Result),
1016				receivedAt: rec.ReceivedAt.UTC(),
1017			}
1018			ts.reports[rec.ReceiptID] = report
1019			rec.Audit.Seq = int64(len(ts.audit)) + 1
1020			ts.audit = append(ts.audit, rec.Audit)
1021			return nil
1022	
1023		case recTaskTimeout:
1024			var rec walTaskTimeout
1025			if err := json.Unmarshal(payload, &rec); err != nil {
1026				return fmt.Errorf("invalid task timeout record: %w", err)
1027			}
1028			state, ok := s.devices[rec.DeviceID]
1029			if !ok {
1030				return fmt.Errorf("task timeout for unknown device %q", rec.DeviceID)
1031			}
1032			ts := findTask(state, rec.TaskID)
1033			if ts == nil {
1034				return fmt.Errorf("device %q timeout for unknown task %d", rec.DeviceID, rec.TaskID)
1035			}
1036			if ts.task.Status != taskStatusInProgress {
1037				return fmt.Errorf("device %q task %d timeout in bad state %q", rec.DeviceID, rec.TaskID, ts.task.Status)
1038			}
1039			if ts.task.Attempts != rec.Attempt {
1040				return fmt.Errorf("device %q task %d timeout attempt mismatch: got %d, want %d", rec.DeviceID, rec.TaskID, rec.Attempt, ts.task.Attempts)
1041			}
1042			if rec.Deadline.IsZero() || rec.FailureReason == "" {
1043				return fmt.Errorf("device %q task %d timeout record is incomplete", rec.DeviceID, rec.TaskID)
1044			}
1045			if rec.Status != taskStatusWaiting && rec.Status != taskStatusFailed {
1046				return fmt.Errorf("device %q task %d timeout has bad resulting status %q", rec.DeviceID, rec.TaskID, rec.Status)
1047			}
1048			ts.task.Status = rec.Status
1049			ts.task.Failures = rec.Failures
1050			ts.task.NextClaimableAt = rec.NextClaimableAt.UTC()
1051			ts.task.FailureReason = rec.FailureReason
1052			if rec.CompletedAt != nil {
1053				t := rec.CompletedAt.UTC()
1054				ts.task.CompletedAt = &t
1055			}
1056			ts.task.Credential = ""
1057			ts.task.ClaimedAt = nil
1058			ts.task.Deadline = nil
1059			rec.Audit.Seq = int64(len(ts.audit)) + 1
1060			ts.audit = append(ts.audit, rec.Audit)
1061			return nil
1062	
1063		case recTaskCancel:
1064			var rec walTaskCancel
1065			if err := json.Unmarshal(payload, &rec); err != nil {
1066				return fmt.Errorf("invalid task cancel record: %w", err)
1067			}
1068			state, ok := s.devices[rec.DeviceID]
1069			if !ok {
1070				return fmt.Errorf("task cancel for unknown device %q", rec.DeviceID)
1071			}
1072			ts := findTask(state, rec.TaskID)
1073			if ts == nil {
1074				return fmt.Errorf("device %q cancel for unknown task %d", rec.DeviceID, rec.TaskID)
1075			}
1076			if ts.task.Status == taskStatusSucceeded || ts.task.Status == taskStatusFailed {
1077				return fmt.Errorf("device %q task %d cancel after end", rec.DeviceID, rec.TaskID)
1078			}
1079			if rec.CanceledAt.IsZero() {
1080				return fmt.Errorf("device %q task %d cancel record is incomplete", rec.DeviceID, rec.TaskID)
1081			}
1082			ts.task.Status = taskStatusCanceled
1083			completedAt := rec.CanceledAt.UTC()
1084			ts.task.CompletedAt = &completedAt
1085			ts.task.Credential = ""
1086			ts.task.ClaimedAt = nil
1087			ts.task.Deadline = nil
1088			rec.Audit.Seq = int64(len(ts.audit)) + 1
1089			ts.audit = append(ts.audit, rec.Audit)
1090			return nil
1091	
1092		default:
1093			return fmt.Errorf("unknown record type %d", recType)
1094		}
1095	}
1096	
1097	func newInstanceID() []byte {
1098		id := make([]byte, 16)
1099		if _, err := rand.Read(id); err != nil {
1100			panic(fmt.Sprintf("cannot generate instance id: %v", err))
1101		}
1102		return id
1103	}
